  const R=sw*4.2;items().forEach(m=>{const on=!hlId||m.id===hlId;const col=pinCol(m);pinPts(m).forEach(a=>{s+=`<circle cx="${a[0]}" cy="${a[1]}" r="${on?R:R*.75}" fill="${col}" stroke="#fff" stroke-width="${sw*.9}" opacity="${on?1:.4}"/><text x="${a[0]}" y="${a[1]+R*.36}" font-size="${(on?R:R*.75)*1.05}" font-weight="900" text-anchor="middle" fill="#fff" opacity="${on?1:.5}" font-family="system-ui,sans-serif">${m.n}</text>`;});});
