/* ══ 31/10 (lot MD) — MODIFS DÉCLARÉES. Ethan : « par défaut on va juste avoir la comparaison avant / après modif, et comme il n'y a pas de pastille par défaut à classer, tout est
   compris ; on va juste créer la possibilité de « déclarer une modif » […] où là on dit ce qu'on veut ressortir : le changement de DN, le nombre de soudures, les pièces ou autre… et
   pointé sur plan, pour déclarer ça en TS ou autre. Les pastilles, l'idée était bien mais ça ne marche pas. » → l'onglet Modifs montre la comparaison marché ↔ réel ; « ＋ Déclarer
   une modif » = une fenêtre au doigt (nom, état, devis, lignes « ce que je veux ressortir » avec propositions tirées des écarts, points sur le plan, note, photos) ; chaque modif
   déclarée = un repère numéroté sur le plan. L'attribution par éléments (lots 2910b → g) reste dans « Avancé », ses modifs restent lisibles et modifiables. ══ */
const DN_LIST=[20,25,32,40,50,65,80,100,125,150,200,250,300,350,400,450,500,600,700,800];
const r2=v=>Math.round(v*100)/100;
const ET_FORM=['propose','commande','note','forfait','corr']; /* TS proposé d'abord (état par défaut d'une modif déclarée) */
function newDraft(){return {edit:null,nom:'',devis:'',etat:'propose',lignes:[],pts:[],note:'',photos:[]};}
const hasDraft=()=>!!(DC.draft&&(DC.draft.lignes.length||DC.draft.pts.length||DC.draft.nom||DC.draft.note||DC.draft.photos.length));
/* ligne de la fenêtre (saisie) ↔ ligne du modèle : la quantité est saisie sans signe + un bouton « en plus / en moins » */
const parseN=v=>{const x=parseFloat(String(v==null?'':v).replace(/\s/g,'').replace(',','.'));return isFinite(x)?x:0;};
function toDraftLine(l){l=declNorm(l);return {nature:l.nature,dn:l.dn||'',dnA:l.dnA||'',dnB:l.dnB||'',k:l.k||'coudes',abs:l.qte?String(Math.abs(l.qte)).replace('.',','):'',sg:l.qte<0?-1:1,unite:l.unite||'',txt:l.txt||'',line:l.line||'',from:l.from||''};}
function toLine(d){const q=Math.abs(parseN(d.abs));return declNorm({nature:d.nature,dn:d.dn,dnA:d.dnA,dnB:d.dnB,k:d.k,qte:d.nature==='dn'?q:(d.sg<0?-q:q),unite:d.unite,txt:d.txt,line:d.line,from:d.from});}
const decls=()=>items().filter(isDecl);
/* propositions (écarts constatés) : calculées à l'ouverture de la fenêtre, à partir des éléments marché → réel */
let PROPS={key:null,list:[]};
function propsOf(){if(!A.marche())return [];let els=[];try{els=elements();}catch(e){els=[];}if(PROPS.key===els)return PROPS.list;let list=[];try{list=declProps(els);}catch(e){console.warn('modifs',e);}PROPS={key:els,list};return list;}
/* ── fenêtre « Déclarer une modif » ── */
export function declOpen(o){o=o||{};if(!A.can('ts.qualify')){A.toast('Réservé au chef / bureau');return false;}if(MU.on)end(true);if(DC.pick){DC.pick=false;pickBar();}
  if(o.edit){const m=items().find(x=>x.id===o.edit&&isDecl(x));if(!m){A.toast('Modif introuvable');return false;}DC.draft={edit:m.id,nom:m.nom||'',devis:m.devis||'',etat:m.etat||'propose',lignes:((m.decl&&m.decl.lignes)||[]).map(toDraftLine),pts:((m.decl&&m.decl.pts)||[]).map(p=>Object.assign({},p)),note:m.note||'',photos:(m.photos||[]).slice()};}
  else if(o.fresh||!hasDraft()||(DC.draft&&DC.draft.edit))DC.draft=newDraft();
  if(o.pts)o.pts.forEach(p=>{if(p&&isFinite(+p.x)&&isFinite(+p.y)&&!DC.draft.pts.some(q=>Math.hypot(q.x-p.x,q.y-p.y)<0.5))DC.draft.pts.push(Object.assign({},p));});
  if(o.line)DC.draft.lignes.push(toDraftLine(o.line));
  DC.pinOpen=null;renderForm();return true;}
function etBtn(et,on){return `<button type="button" class="dclEtB${on?' on':''}" data-mod="dcl-et:${et}" style="${on?`background:${MOD_COL[et]};border-color:${MOD_COL[et]};color:#fff`:''}" title="${esc(MOD_ET_LONG[et]||'')}">${esc(MOD_ET[et])}</button>`;}
const dnSel=(i,f,v,ph)=>{const val=+v||0;const L=DN_LIST.includes(val)||!val?DN_LIST:DN_LIST.concat([val]).sort((a,b)=>a-b);return `<select class="f dclDn" data-dcl="${i}:${f}" aria-label="${esc(ph)}"><option value="">${esc(ph)}</option>${L.map(d=>`<option value="${d}"${d===val?' selected':''}>DN ${d}</option>`).join('')}</select>`;};
const sgBtns=i=>{const d=DC.draft.lignes[i];return `<span class="dclSg"><button type="button" class="${d.sg>0?'on':''}" data-mod="dcl-sign:${i}:1" aria-label="en plus">＋ en plus</button><button type="button" class="${d.sg<0?'on':''}" data-mod="dcl-sign:${i}:-1" aria-label="en moins">− en moins</button></span>`;};
const qIn=(i,ph,unit)=>`<span class="dclQ"><input class="f" data-dcl="${i}:abs" inputmode="decimal" value="${esc(DC.draft.lignes[i].abs)}" placeholder="${esc(ph)}" aria-label="${esc(ph)}">${unit?`<span class="dim">${esc(unit)}</span>`:''}</span>`;
function lineFields(i){const d=DC.draft.lignes[i];
  if(d.nature==='dn')return `<div class="dclF">${dnSel(i,'dnA',d.dnA,'DN avant')}<span class="dclArr">→</span>${dnSel(i,'dnB',d.dnB,'DN après')}<span class="dim">sur</span>${qIn(i,'longueur','m')}</div>`;
  if(d.nature==='ml')return `<div class="dclF">${sgBtns(i)}${qIn(i,'longueur','m')}${dnSel(i,'dn',d.dn,'DN')}</div>`;
  if(d.nature==='soud')return `<div class="dclF">${sgBtns(i)}${qIn(i,'nombre','soudures')}${dnSel(i,'dn',d.dn,'DN')}</div>`;
  if(d.nature==='piece')return `<div class="dclF"><select class="f" data-dcl="${i}:k" aria-label="pièce">${DECL_PC.map(([k,a])=>`<option value="${k}"${d.k===k?' selected':''}>${esc(a)}</option>`).join('')}</select>${d.k==='autre'?`<input class="f dclTxt" data-dcl="${i}:txt" value="${esc(d.txt)}" placeholder="laquelle ?" aria-label="pièce">`:''}${sgBtns(i)}${qIn(i,'nombre','')}${dnSel(i,'dn',d.dn,'DN')}</div>`;
  return `<div class="dclF"><input class="f dclTxt" data-dcl="${i}:txt" value="${esc(d.txt)}" placeholder="ex. fourreau, traversée de voirie, reprise d'enrobé" aria-label="ce que c'est">${sgBtns(i)}${qIn(i,'quantité','')}<input class="f dclU" data-dcl="${i}:unite" value="${esc(d.unite)}" placeholder="unité" aria-label="unité"></div>`;}
function lineHTML(i){const d=DC.draft.lignes[i];return `<div class="dclLn" data-dclln="${i}"><div class="dclLnH"><select class="f" data-dcl="${i}:nature" aria-label="nature">${DECL_NAT.map(([k,l])=>`<option value="${k}"${d.nature===k?' selected':''}>${esc(l)}</option>`).join('')}</select><button type="button" class="dclX" data-mod="dcl-rm:${i}" aria-label="Retirer cette ligne">✕</button></div>${lineFields(i)}<div class="dclPrev" data-dclprev="${i}">${esc(declLineTxt(toLine(d)))}${d.from?' <span class="dim">· '+esc(d.from)+'</span>':''}</div></div>`;}
function formHTML(){const d=DC.draft;const Mo=modifsOf(A.net());const ed=d.edit?Mo.items.find(m=>m.id===d.edit):null;const n=ed?ed.n:nextN(Mo);const P=propsOf();const have=new Set(d.lignes.map(x=>declKey(toLine(x))+'|'+toLine(x).qte));const ts=isTS(d.etat);
  return `<div class="dclForm"><h2 style="margin:0 0 2px">✍ ${ed?'Modifier la modif n°'+n:'Déclarer une modif'}</h2><div class="dim dclHint">Par défaut, tout est compris dans le marché. Dis seulement ce que tu veux ressortir, et où (pointé sur le plan).</div>
   <label class="dclL">Nom<input class="f" data-dcf="nom" value="${esc(d.nom)}" placeholder="Modif n°${n} — ex. antenne B passée en DN 100"></label>
   <div class="dclL">État<div class="dclEt">${ET_FORM.map(et=>etBtn(et,d.etat===et)).join('')}</div></div>
   <label class="dclL"><span>N° de devis ${d.etat==='commande'?'<b>(TS commandé : obligatoire)</b>':ts?'<span class="dim">(si tu l\'as)</span>':'<span class="dim">(facultatif)</span>'}</span><input class="f" data-dcf="devis" value="${esc(d.devis)}" placeholder="ex. DEV-2026-046"></label>
   <h4 class="dclH">Ce que je veux ressortir <span class="dim">${d.lignes.length||''}</span></h4>
   ${d.lignes.map((x,i)=>lineHTML(i)).join('')||'<div class="dim dclEmpty">Aucune ligne : touche un écart constaté ci-dessous, ou ajoute une ligne.</div>'}
   <div class="dclAdd">${DECL_NAT.map(([k,l])=>`<button type="button" class="btn sm" data-mod="dcl-add:${k}">＋ ${esc(l)}</button>`).join('')}</div>
   ${P.length?`<div class="dclProps"><div class="dim" style="font-size:12.5px">Écarts constatés (marché → réel) — un toucher pour l'ajouter, modifiable ensuite :</div><div class="dclPl">${P.slice(0,DC.allProps?60:12).map((p,i)=>{const on=have.has(declKey(p)+'|'+p.qte);return `<button type="button" class="dclP${on?' on':''}" data-mod="dcl-prop:${i}" ${on?'disabled':''}>${on?'✓':'＋'} ${esc(p.lab)}${p.from?' <span class="dim">· '+esc(p.from)+'</span>':''}</button>`;}).join('')}${P.length>12&&!DC.allProps?`<button type="button" class="dclP more" data-mod="dcl-allprops">… ${P.length-12} autre${P.length-12>1?'s':''}</button>`:''}</div></div>`:A.marche()?'<div class="dim" style="font-size:12.5px;margin-top:6px">Aucun écart constaté entre le marché et le réel.</div>':''}
   <h4 class="dclH">Où ? <span class="dim">${d.pts.length?d.pts.length+' point'+(d.pts.length>1?'s':''):''}</span></h4>
   ${d.pts.length?`<div class="dclPts">${d.pts.map((p,i)=>`<div class="dclPt"><span class="dclPn">${i+1}</span><span style="flex:1;min-width:0">${esc(p.lineName||p.line||'point sur le plan')}${p.line&&p.m!=null?' · PK '+fmtFR(p.m)+' m':''}</span><button type="button" class="dclX" data-mod="dcl-pt-rm:${i}" aria-label="Retirer ce point">✕</button></div>`).join('')}</div>`:''}
   <button type="button" class="btn dclPick" data-mod="dcl-pick">📍 ${d.pts.length?'Repointer / ajouter des points':'Pointer sur le plan'}</button>
   <label class="dclL"><span>Note <span class="dim">(facultatif)</span></span><textarea class="f" data-dcf="note" rows="2" placeholder="ce qui s'est passé, qui l'a demandé…">${esc(d.note)}</textarea></label>
   <div class="dclPh">${d.photos.map((u,i)=>`<span class="dclTh"><img src="${esc(u)}" alt="photo ${i+1}"><button type="button" class="dclX" data-mod="dcl-ph-rm:${i}" aria-label="Retirer la photo">✕</button></span>`).join('')}<label class="btn sm">📷 Photo<input type="file" accept="image/*" capture="environment" data-dcf-photo="1" style="display:none"></label></div>
   <div class="dclMsg" id="dclMsg">${esc(DC.msg||'')}</div>
   <div class="actions dclAct"><button type="button" class="btn" data-mod="dcl-cancel">Annuler</button><button type="button" class="btn primary" data-mod="dcl-save">${ed?'Enregistrer la modif n°'+n:'Déclarer la modif n°'+n}</button></div></div>`;}
function renderForm(){if(!DC.draft)return;const prev=document.querySelector('#modal .box');const y=prev&&prev.querySelector('.dclForm')?prev.scrollTop:0;A.openModal(formHTML());DC.msg='';const box=document.querySelector('#modal .box');if(!box)return;box.classList.add('dclBox');box.scrollTop=y;
  const onIn=e=>{const t=e.target;if(!t||!t.dataset)return;if(t.dataset.dcf){DC.draft[t.dataset.dcf]=t.value;return;}if(t.dataset.dcfPhoto){const f=t.files&&t.files[0];if(f)addPhoto(f);return;}
    if(t.dataset.dcl){const [i,f]=t.dataset.dcl.split(':');const d=DC.draft.lignes[+i];if(!d)return;d[f]=t.value;if(f==='nature'){if(d.nature==='dn')d.sg=1;renderForm();return;}if(f==='k'&&e.type==='change'){renderForm();return;}const pv=box.querySelector(`[data-dclprev="${i}"]`);if(pv)pv.textContent=declLineTxt(toLine(d));}};
  box.addEventListener('input',onIn);box.addEventListener('change',onIn);}
async function addPhoto(f){try{const d=await A.compressPhoto(f);let u=null;try{u=await A.uploadPhoto('modif',d);}catch(e){u=null;}if(!DC.draft)return;DC.draft.photos.push(u||d);renderForm();}catch(e){A.toast('Photo illisible');}}
function declSave(){const d=DC.draft;if(!d)return null;const Mo=modifsOf(A.net());if(!Mo){A.toast('Aucun chantier ouvert');return null;}const say=t=>{DC.msg=t;const el=document.getElementById('dclMsg');if(el)el.textContent=t;A.toast(t);};
  const lignes=d.lignes.map(toLine);if(!lignes.length){say('Ajoute au moins une ligne : ce que tu veux ressortir (un écart constaté, ou ＋ une ligne)');return null;}
  const bad=lignes.findIndex(l=>declLineErr(l));if(bad>=0){say(`Ligne ${bad+1} : ${declLineErr(lignes[bad])}`);return null;}
  const devis=String(d.devis||'').trim().slice(0,40);if(d.etat==='commande'&&!devis){say('TS commandé : indique le n° de devis');return null;}
  const now=new Date().toISOString(),by=A.userName();const pts=d.pts.map(p=>{const o={x:r2(+p.x),y:r2(+p.y)};if(p.line){o.line=p.line;o.m=p.m==null?null:Math.round(+p.m*10)/10;o.lineName=p.lineName||p.line;}return o;});
  const note=String(d.note||'').trim().slice(0,600);let m=d.edit?Mo.items.find(x=>x.id===d.edit):null;const n=m?m.n:nextN(Mo);const nom=String(d.nom||'').trim().slice(0,90)||('Modif n°'+n);
  if(m){const ch=[];if(m.etat!==d.etat)ch.push('état : '+(MOD_ET[m.etat]||m.etat)+' → '+MOD_ET[d.etat]);if((m.devis||'')!==devis)ch.push('devis '+(devis||'retiré'));const L0=((m.decl&&m.decl.lignes)||[]).map(declLineTxt).join(' · '),L1=lignes.map(declLineTxt).join(' · ');if(L0!==L1)ch.push('lignes : '+L1);const P0=((m.decl&&m.decl.pts)||[]).length;if(P0!==pts.length)ch.push(pts.length+' point'+(pts.length>1?'s':''));
    Object.assign(m,{nom,devis,etat:d.etat,decl:{lignes,pts},note,photos:d.photos.slice()});(m.log=m.log||[]).push({at:now,by,txt:ch.join(' · ')||'modifiée'});}
  else{m={id:newId(Mo),n,kind:'decl',nom,devis,etat:d.etat,decl:{lignes,pts},note,photos:d.photos.slice(),at:now,by,v:versionOf(Mo,A.marche(),A.savedAt()),log:[{at:now,by,txt:'déclarée : '+lignes.map(declLineTxt).join(' · ')}]};Mo.items.push(m);}
  const ln=pts.find(p=>p.line);if(ln){m.line=ln.line;const a=A.affOf(ln.line);if(a!=null&&a!=='')m.aff=a;else delete m.aff;}else{delete m.line;let s='';try{s=A.scopeAff?A.scopeAff():'';}catch(e){s='';}if(s)m.aff=s;else delete m.aff;}
  A.save();const edit=!!d.edit;DC.draft=null;DC.msg='';A.closeModal();A.renderAll();A.toast(`Modif n°${m.n} ${edit?'enregistrée':'déclarée'} · ${MOD_ET[m.etat]}${pts.length?'':' — pas pointée sur le plan'}`);return m;}
/* ── pointer sur le plan ── */
export const picking=()=>!!DC.pick;
export function pickStart(o){o=o||{};if(!A.can('ts.qualify')){A.toast('Réservé au chef / bureau');return false;}if(MU.on)end(true);A.endOtherPoses();if(!DC.draft||o.first&&!hasDraft())DC.draft=newDraft();
  DC.pickFirst=!!o.first;DC.ptsBak=DC.draft.pts.map(p=>Object.assign({},p));DC.note='';DC.pick=true;A.closeModal();A.closeSheet();A.state.tab='plan';A.renderAll();pickBar();A.renderPlan();return true;}
export function pickTap(x,y){if(!DC.pick||!DC.draft)return;const k=A.k();const P=DC.draft.pts;const i=P.findIndex(p=>Math.hypot(p.x-x,p.y-y)*k<=26);
  if(i>=0){P.splice(i,1);DC.note=`✕ point ${i+1} retiré`;}
  else{if(P.length>=12){A.toast('12 points au plus pour une modif');return;}let n=null;try{n=A.nearest(x,y);}catch(e){n=null;}const pt={x:r2(x),y:r2(y)};
    if(n&&n.line&&n.d*k<=48){if(n.d*k<=28){pt.x=r2(n.x);pt.y=r2(n.y);}pt.line=n.line;pt.m=Math.round(n.m*10)/10;pt.lineName=A.lineName(n.line);}
    P.push(pt);DC.note=`✓ point ${P.length}${pt.line?' · '+esc(pt.lineName||pt.line)+' · PK '+fmtFR(pt.m)+' m':' (hors réseau)'}`;}
  pickBar();A.renderPlan();}
export function pickEnd(cancel,silent){if(!DC.pick)return;DC.pick=false;DC.note='';if(cancel&&DC.draft&&DC.ptsBak)DC.draft.pts=DC.ptsBak;DC.ptsBak=null;pickBar();A.renderPlan();if(silent)return;if(cancel&&DC.pickFirst){DC.draft=null;return;}renderForm();}
function pickBar(){let el=document.getElementById('modPickBar');if(!DC.pick){if(el)el.style.display='none';document.body.classList.remove('mod-pick');return;}document.body.classList.add('mod-pick');
  if(!el){const host=document.getElementById('canvas')||document.body;el=document.createElement('div');el.id='modPickBar';host.appendChild(el);['pointerdown','touchstart','wheel'].forEach(ev=>el.addEventListener(ev,e=>e.stopPropagation(),{passive:true}));}
  const n=DC.draft?DC.draft.pts.length:0;el.style.display='flex';
  el.innerHTML=`<div class="mbH"><b>📍 Pointer la modif</b><span class="mbLeg"><i class="y"></i>écart <i class="v"></i>DN changé <i class="g"></i>marché</span><button class="mbEnd" data-mod="pick-cancel">Annuler</button></div>${DC.note?`<div class="mbNote">${DC.note}</div>`:''}<div class="mbMsg">Touche l'endroit de la modif (plusieurs points possibles ; re-touche un point pour l'enlever).</div><div class="mbTools">${n?'<button class="mbT" data-mod="pick-undo" title="enlever le dernier point">↶</button><button class="mbT" data-mod="pick-clear">Vider</button>':''}<span class="mbCnt"><b>${n}</b> point${n>1?'s':''}</span><button class="mbGo" data-mod="pick-ok">✓ ${DC.pickFirst&&!DC.draft.lignes.length?'Suite : ce que je ressors':'Terminé'}</button></div>`;}
/* ── repères sur le plan ── */
function pinPts(m){if(isDecl(m))return ((m.decl&&m.decl.pts)||[]).map(p=>[+p.x,+p.y]).filter(p=>isFinite(p[0])&&isFinite(p[1]));const els=(m.els||[]).map(byId).filter(Boolean);if(!els.length)return [];const e=els[0];const an=anchors(e);const a=e.at&&e.at.length?e.at[0]:an[Math.floor(an.length/2)];return a?[a]:[];}
const pinCol=m=>isDecl(m)?(MOD_COL[m.etat]||'#b88d12'):modColor(m);
function pinsOverlay(k){const Mo=modifsOf(A.net());if(!Mo||!Mo.items.length)return '';let s='';const lab=k>=0.9;
  items().forEach(m=>{if(!isDecl(m)&&MU.on)return; /* en mode « attribuer », l'ancienne modif est dessinée par ses éléments */const P=pinPts(m);if(!P.length)return;const col=pinCol(m);const t=isDecl(m)?(MOD_ET[m.etat]||''):'';const nm=String(m.nom||'');
    P.forEach((a,i)=>{s+=`<g data-modpin="${esc(m.id)}" transform="translate(${a[0]} ${a[1]}) scale(${1/k})" style="cursor:pointer"><circle r="23" fill="#fff" fill-opacity=".01"/><circle r="15" fill="${col}" stroke="#fff" stroke-width="3"/><text y="5" font-size="${m.n>99?11:13}" font-weight="900" text-anchor="middle" fill="#fff" font-family="system-ui,sans-serif" style="pointer-events:none">${m.n}</text>${lab&&i===0?`<text x="20" y="-9" font-size="11.5" font-weight="800" fill="${col}" stroke="#fff" stroke-width="3.2" paint-order="stroke" font-family="system-ui,sans-serif" style="pointer-events:none">n°${m.n}${t?' · '+esc(t):''}${k>=2.5&&nm?' · '+esc(nm.length>28?nm.slice(0,27)+'…':nm):''}</text>`:''}</g>`;});});
  return s;}
function draftOverlay(k){const P=DC.draft?DC.draft.pts:[];return P.map((p,i)=>`<g transform="translate(${p.x} ${p.y}) scale(${1/k})" style="pointer-events:none"><circle r="20" fill="#1f5fd6" opacity=".22"/><circle r="13" fill="#1f5fd6" stroke="#fff" stroke-width="3"/><text y="5" font-size="13" font-weight="900" text-anchor="middle" fill="#fff" font-family="system-ui,sans-serif">${i+1}</text></g>`).join('');}
export const elsShown=()=>!!(MU.on||(A&&A.state&&A.state.show&&A.state.show.modEls===true));
export function overlay(k){let s='';const sh=(A.state&&A.state.show)||{};if(elsShown()){try{s+=elsOverlay(k);}catch(e){console.warn('modifs',e);}}if(sh.ts!==false||DC.pick)s+=pinsOverlay(k);if(DC.pick)s+=draftOverlay(k);return s;}
/* toucher un repère → la fiche de la modif (lecture pour tous, Modifier / Retirer pour le chef / bureau) */
export function openPin(id){const m=items().find(x=>x.id===id);if(!m){A.toast('Modif introuvable');return;}DC.pinOpen=id;A.openModal(`${isDecl(m)?declCardHTML(m,{modal:true}):cardHTML(m)}<div class="actions"><button class="btn block" data-close>Fermer</button></div>`);}
function goDecl(m){const P=pinPts(m);if(!P.length){A.toast('Pas pointée sur le plan');return;}let x0=1e15,y0=1e15,x1=-1e15,y1=-1e15;P.forEach(p=>{x0=Math.min(x0,p[0]);y0=Math.min(y0,p[1]);x1=Math.max(x1,p[0]);y1=Math.max(y1,p[1]);});A.closeModal();A.state.tab='plan';A.renderAll();A.fit([x0-15,y0-15,x1+15,y1+15]);}
/* ── carte d'une modif déclarée (onglet, repère) ── */
function declCardHTML(m,o){o=o||{};const canEd=A.can('ts.qualify');const col=MOD_COL[m.etat]||'#b88d12';const L=(m.decl&&m.decl.lignes)||[];const P=(m.decl&&m.decl.pts)||[];const log=m.log||[];const last=log.length>1?log[log.length-1]:null;const open=o.modal||MU.fold[m.id]!==false;
  return `<div class="mdCard dclCard" data-modcard="${esc(m.id)}" style="border-left:5px solid ${col}"><div class="mdHd"${o.modal?'':` data-mod="fold:${esc(m.id)}"`}>${o.modal?'':`<span class="mdChev">${open?'▾':'▸'}</span>`}<span class="mdBadge" style="background:${col}">n°${m.n}</span><b style="flex:1 1 140px;min-width:0">${esc(m.nom||'')}</b>${chip(m.etat)}${m.devis?`<span class="mdDev">devis ${esc(m.devis)}</span>`:isTS(m.etat)?'<span class="mdM" style="font-size:12px">devis manquant</span>':''}</div>
   ${open?`<ul class="dclLines">${L.map(l=>`<li>${esc(declLineTxt(l))}</li>`).join('')||'<li class="dim">—</li>'}</ul>
   <div class="mdMeta">📍 ${P.length?P.map((p,i)=>esc((P.length>1?(i+1)+' · ':'')+(p.lineName||p.line||'point sur le plan')+(p.line&&p.m!=null?' · PK '+fmtFR(p.m)+' m':''))).join(' ; '):'<span class="mdWarn">pas pointée sur le plan</span>'}</div>
   ${m.note?`<div class="dclNote">${esc(m.note)}</div>`:''}${(m.photos||[]).length?`<div class="thumbs" style="margin:4px 0">${m.photos.map(u=>`<div class="thumb"><img src="${esc(u)}" alt="photo"></div>`).join('')}</div>`:''}
   <div class="mdMeta">déclarée le ${esc(dFR(m.at))} par ${esc(m.by||'')}${last?' · dernière modification : '+esc(dFR(last.at))+' ('+esc(last.by||'')+')':''}</div>
   ${log.length>1?`<details class="dclLog"><summary>Journal (${log.length})</summary>${log.map(x=>`<div>${esc(dFR(x.at))} · ${esc(x.by||'')} · ${esc(x.txt||'')}</div>`).join('')}</details>`:''}
   <div class="row" style="gap:6px;flex-wrap:wrap;display:flex;margin-top:6px">${canEd?`<button class="btn sm" data-mod="dcl-edit:${esc(m.id)}">✎ Modifier</button>`:''}${P.length&&!o.noGo?`<button class="btn sm" data-mod="dcl-go:${esc(m.id)}">🗺 Voir sur le plan</button>`:''}${canEd?(MU.sure===m.id?`<button class="btn sm" data-mod="del:${esc(m.id)}" style="color:#fff;background:#c2362c;border-color:#c2362c">Confirmer : retirer la modif n°${m.n}</button>`:`<button class="btn sm" data-mod="del:${esc(m.id)}" style="color:#c2362c">🗑 Retirer</button>`):''}</div>`:''}</div>`;}
/* récap des modifs déclarées, par état */
function declRecapHTML(){const R=declRecap(decls());const ets=MOD_ORDER.filter(et=>R[et]&&R[et].length);if(!ets.length)return '';
  return `<h3 style="margin:14px 0 4px">Récap par état <span class="muted" style="font-weight:400;font-size:12px">— modifs déclarées, lignes additionnées</span></h3><div class="dclRecap">${ets.map(et=>`<div class="dclRc"><div class="dclRcH">${chip(et)}</div><ul>${R[et].map(r=>`<li>${esc(r.lab)} <span class="dim">· n°${r.mods.join(', n°')}</span></li>`).join('')}</ul></div>`).join('')}</div>`;}
/* résumé des écarts (en-tête de l'onglet) */
function ecartsTxt(){let D=null;try{D=A.diff();}catch(e){D=null;}if(!D||!D.tot)return '';const d=D.tot.d||{};const W2={ml:['m','m'],soud:['soudure','soudures'],coudes:['coude','coudes'],tes:['té','tés'],reduc:['réduction','réductions'],vannes:['vanne','vannes'],purges:['purge','purges'],vidanges:['vidange','vidanges'],bouchons:['fin de ligne','fins de ligne'],extru:['manchon extrudé','manchons extrudés']};
  const out=Object.keys(W2).filter(k=>Math.abs(+d[k]||0)>(k==='ml'?0.5:0)).map(k=>{const v=+d[k];const a=Math.abs(v);return `<b class="${v>0?'mdP':'mdM'}">${v>0?'+':'−'}${fmtFR(a)}${k==='ml'?' m':' '+W2[k][a>1?1:0]}</b>`;});
  const ndn=(D.rows||[]).reduce((n,r)=>n+((r.dnd||[]).length),0);if(ndn)out.push(`<b>${ndn} changement${ndn>1?'s':''} de DN</b>`);return out.join(' · ');}
/* ── clics ── */
export function handleClick(e){const t=e.target.closest('[data-mod]');if(!t)return false;const v=t.dataset.mod;const [k,...rest]=v.split(':');const arg=rest.join(':');e.stopPropagation();
  switch(k){
    case 'start':start({});return true;case 'startwith':start({sel:arg.split(',').filter(Boolean),panel:true});return true;case 'end':end(false);return true;
    case 'lasso':MU.lasso=MU.lasso?null:{pts:[]};MU.lasso&&(MU.lasso.pts=[]);if(MU.lasso&&!MU.lasso.pts.length)MU.lasso={pts:[],armed:true};bar();A.renderPlan();return true;
    case 'undo':{const u=MU.undo.pop();if(u)MU.sel=u;refresh();return true;}case 'clear':MU.undo.push(MU.sel.slice());MU.sel=[];MU.qual={};refresh();return true;
    case 'rm':MU.undo.push(MU.sel.slice());removeIds([arg]);return true;case 'add':addMany([arg]);return true;
    case 'takev':{const ids=freeEls().filter(x=>x.v===+arg).map(x=>x.id);if(!MU.on){start({sel:ids,panel:true});A.toast(ids.length+' éléments pris : qualifie-les dans le panneau');}else{addMany(ids);const p=document.getElementById('modPanel');if(p)p.scrollTop=0;}return true;}
    case 'goto':goto([arg]);return true;case 'gotom':{const m=modifsOf(A.net()).items.find(x=>x.id===arg);if(m)goto(m.els||[]);return true;}
    case 'q':{const i=arg.lastIndexOf(':');const key=arg.slice(0,i),et=arg.slice(i+1);MU.qual[key]=MU.qual[key]===et?undefined:et;panel();return true;}
    case 'qall':compareEls(MU.sel.map(byId).filter(Boolean)).forEach(r=>{MU.qual[r.key]=arg;});panel();return true;
    case 'create':commit();return true;case 'cancel':MU.undo.push(MU.sel.slice());MU.sel=[];MU.qual={};MU.edit=null;MU._fresh=true;refresh();return true;
    case 'panel':MU.panel=true;panel();return true;case 'panelclose':MU.panel=false;panel();return true;
    case 'vf':MU.vf=+arg===MU.vf?0:+arg;refresh();return true;case 'fold':MU.fold[arg]=MU.fold[arg]===false;A.renderAll();return true;
    case 'edit':start({edit:arg});return true;
    case 'del':if(MU.sure===arg){removeModif(arg);if(DC.pinOpen===arg){DC.pinOpen=null;A.closeModal();}A.renderAll();}else{MU.sure=arg;A.renderAll();if(DC.pinOpen===arg)openPin(arg);}return true;
    case 'drop':{const i=arg.indexOf(':');const mid=arg.slice(0,i),eid=arg.slice(i+1);const Mo=modifsOf(A.net());const m=Mo.items.find(x=>x.id===mid);if(m){m.els=(m.els||[]).filter(x=>x!==eid);(m.log=m.log||[]).push({at:new Date().toISOString(),by:A.userName(),txt:'élément disparu retiré'});if(!m.els.length)Mo.items=Mo.items.filter(x=>x!==m);A.save();A.renderAll();}return true;}
    case 'export':{const html=exportHTML();if(!html){A.toast('Pas de marché figé');return true;}A.openWin(html);return true;}
    case 'diag':{if(A.diag)A.diag();return true;}
    /* 31/10 (lot MD) : modifs déclarées */
    case 'decl':declOpen({});return true;case 'dcl-new':declOpen({fresh:true});return true;
    case 'dcl-et':if(DC.draft){DC.draft.etat=arg;renderForm();}return true;
    case 'dcl-add':if(DC.draft){DC.draft.lignes.push({nature:arg,dn:'',dnA:'',dnB:'',k:'coudes',abs:'',sg:1,unite:arg==='autre'?'u':'',txt:'',line:'',from:''});renderForm();}return true;
    case 'dcl-rm':if(DC.draft){DC.draft.lignes.splice(+arg,1);renderForm();}return true;
    case 'dcl-sign':{const [i,sv]=arg.split(':');const d=DC.draft&&DC.draft.lignes[+i];if(d){d.sg=+sv<0?-1:1;renderForm();}return true;}
    case 'dcl-prop':{const p=propsOf()[+arg];if(p&&DC.draft){DC.draft.lignes.push(toDraftLine(p));renderForm();}return true;}
    case 'dcl-allprops':DC.allProps=true;renderForm();return true;
    case 'dcl-pick':pickStart({});return true;
    case 'dcl-pt-rm':if(DC.draft){DC.draft.pts.splice(+arg,1);renderForm();}return true;
    case 'dcl-ph-rm':if(DC.draft){DC.draft.photos.splice(+arg,1);renderForm();}return true;
    case 'dcl-save':declSave();return true;
    case 'dcl-cancel':DC.draft=null;DC.msg='';DC.allProps=false;A.closeModal();return true;
    case 'dcl-edit':declOpen({edit:arg});return true;
    case 'dcl-go':{const m=items().find(x=>x.id===arg);if(m)goDecl(m);return true;}
    case 'dcl-here':{const [x,y,line,mm]=arg.split(',');const pt={x:+x,y:+y};if(line){pt.line=line;pt.m=+mm;pt.lineName=A.lineName(line);}A.closeSheet();declOpen({pts:[pt]});return true;}
    case 'pin':openPin(arg);return true;
    case 'pick-ok':pickEnd(false);return true;case 'pick-cancel':pickEnd(true);return true;
    case 'pick-undo':if(DC.draft&&DC.draft.pts.length){DC.draft.pts.pop();DC.note='↶ dernier point retiré';pickBar();A.renderPlan();}return true;
    case 'pick-clear':if(DC.draft){DC.draft.pts=[];DC.note='';pickBar();A.renderPlan();}return true;
    case 'adv':MU.adv=!MU.adv;A.renderAll();return true;
    case 'els-layer':{const sh=A.state.show;sh.modEls=sh.modEls!==true;try{if(A.saveShow)A.saveShow();}catch(e){}A.renderAll();A.toast(sh.modEls?'Éléments − / + affichés sur le plan':'Éléments − / + cachés sur le plan');return true;}}
  return false;}
export function handleChange(e){const t=e.target;if(!t||!t.dataset||!t.dataset.modPick)return false;const id=t.dataset.modPick;if(!MU.on){if(t.checked)start({sel:[id],panel:true});return true;}if(t.checked){if(!MU.sel.includes(id))addMany([id]);}else removeIds([id]);return true;}
